import numpy as np
print("First inference decision map (1=water):")
for r in range(14):
    print("".join("W" if decision[r,c]==1 else "." for c in range(14)))
# manual connectivity (4-neighbor)
def components(mask):
    seen = np.zeros_like(mask, bool)
    comps = []
    for r in range(mask.shape[0]):
        for c in range(mask.shape[1]):
            if mask[r,c] and not seen[r,c]:
                stack=[(r,c)]; seen[r,c]=True; comp=[]
                while stack:
                    y,x = stack.pop(); comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<mask.shape[0] and 0<=nx<mask.shape[1] and mask[ny,nx] and not seen[ny,nx]:
                            seen[ny,nx]=True; stack.append((ny,nx))
                comps.append(comp)
    return comps
comps = components(decision==1)
print("n components:", len(comps))
for i,comp in enumerate(comps):
    print(f"comp {i}: size={len(comp)} cells={comp}")

