import numpy as np
# low margin
order = np.argsort(margin)
print("lowest 15 margins:")
for idx in order[:15]:
    r,c = np.unravel_index(idx, margin.shape)
    print((r,c), round(margin[r,c],4), "dec:", decision[r,c], "sdec:", second_decision[r,c])

# boundary: 4-neighbor disagreement
def neighbors(r,c):
    for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
        rr,cc=r+dr,c+dc
        if 0<=rr<14 and 0<=cc<14:
            yield rr,cc
boundary = np.zeros((14,14), bool)
for r in range(14):
    for c in range(14):
        for rr,cc in neighbors(r,c):
            if decision[rr,cc]!=decision[r,c]:
                boundary[r,c]=True
print("n boundary:", boundary.sum())

# isolated: all 4 neighbors (that exist) disagree
isolated = np.zeros((14,14), bool)
for r in range(14):
    for c in range(14):
        nb = list(neighbors(r,c))
        if all(decision[rr,cc]!=decision[r,c] for rr,cc in nb):
            isolated[r,c]=True
print("n isolated:", isolated.sum())
print("isolated coords:", [ (r,c) for r in range(14) for c in range(14) if isolated[r,c] ])

# entropy of 3x3 neighborhood (fraction of 1s)
ent = np.zeros((14,14))
for r in range(14):
    for c in range(14):
        vals=[]
        for rr in range(max(0,r-1), min(14,r+2)):
            for cc in range(max(0,c-1), min(14,c+2)):
                vals.append(decision[rr,cc])
        p = np.mean(vals)
        if 0<p<1:
            ent[r,c] = -(p*np.log(p)+(1-p)*np.log(1-p))
print("top 15 entropy:")
for idx in np.argsort(ent)[::-1][:15]:
    r,c=np.unravel_index(idx,ent.shape)
    print((r,c), round(ent[r,c],4), "dec:", decision[r,c], "margin:", round(margin[r,c],4))

