import numpy as np
H, W = 14, 14

# For each window, compute:
# 1. min_margin = min(margin, second_margin)  -> lower = more uncertain
# 2. disagree = 1 if decision != second_decision
# 3. boundary score: fraction of 4-neighbors with different decision (first inference)

min_margin = np.minimum(margin, second_margin)
disagree = (decision != second_decision).astype(int)

# Boundary score using first decision
boundary = np.zeros((H,W))
for r in range(H):
    for c in range(W):
        nbs = []
        if r>0: nbs.append(decision[r-1,c])
        if r<H-1: nbs.append(decision[r+1,c])
        if c>0: nbs.append(decision[r,c-1])
        if c<W-1: nbs.append(decision[r,c+1])
        if nbs:
            boundary[r,c] = np.mean([d != decision[r,c] for d in nbs])

# Also boundary using second decision
boundary2 = np.zeros((H,W))
for r in range(H):
    for c in range(W):
        nbs = []
        if r>0: nbs.append(second_decision[r-1,c])
        if r<H-1: nbs.append(second_decision[r+1,c])
        if c>0: nbs.append(second_decision[r,c-1])
        if c<W-1: nbs.append(second_decision[r,c+1])
        if nbs:
            boundary2[r,c] = np.mean([d != second_decision[r,c] for d in nbs])

# Combined suspect score: weight low margin, disagreement, and boundary
# Normalize each to [0,1]
mm_norm = 1 - min_margin / min_margin.max()  # higher = lower margin = more suspect
bnd = np.maximum(boundary, boundary2)  # max boundary score

# Let's look at the top candidates
scores = []
for r in range(H):
    for c in range(W):
        s = 0.4*mm_norm[r,c] + 0.3*disagree[r,c] + 0.3*bnd[r,c]
        scores.append((s, r, c, min_margin[r,c], disagree[r,c], bnd[r,c]))

scores.sort(reverse=True)
print("Top 25 suspect windows:")
print(f"{'score':>6} {'row':>3} {'col':>3} {'min_marg':>8} {'disagr':>6} {'bnd':>5}")
for s,r,c,mm,dg,bn in scores[:25]:
    print(f"{s:6.3f} {r:3d} {c:3d} {mm:8.4f} {dg:6d} {bn:5.2f}")

