def n4(r, c):
    cnt = 0
    tot = 0
    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
        rr, cc = r+dr, c+dc
        if 0 <= rr < H and 0 <= cc < W:
            tot += 1
            if water[rr, cc]:
                cnt += 1
    return cnt, tot

def n8(r, c):
    cnt = 0
    tot = 0
    for dr in [-1,0,1]:
        for dc in [-1,0,1]:
            if dr==0 and dc==0: continue
            rr, cc = r+dr, c+dc
            if 0 <= rr < H and 0 <= cc < W:
                tot += 1
                if water[rr, cc]:
                    cnt += 1
    return cnt, tot

print("Water pixels: (r,c) margin n4 n8")
for r in range(H):
    for c in range(W):
        if water[r,c]:
            c4, t4 = n4(r,c)
            c8, t8 = n8(r,c)
            print(f"({r},{c}) m={margin[r,c]:.4f} n4={c4}/{t4} n8={c8}/{t8}")

