import numpy as np
from collections import deque
H, W = decision.shape

def components(mask):
    lab = np.zeros_like(mask, dtype=int)
    cur = 0
    for r in range(H):
        for c in range(W):
            if mask[r,c] and lab[r,c]==0:
                cur += 1
                q = deque([(r,c)])
                lab[r,c]=cur
                while q:
                    a,b = q.popleft()
                    for dr in (-1,0,1):
                        for dc in (-1,0,1):
                            if dr==0 and dc==0: continue
                            rr,cc = a+dr,b+dc
                            if 0<=rr<H and 0<=cc<W and mask[rr,cc] and lab[rr,cc]==0:
                                lab[rr,cc]=cur
                                q.append((rr,cc))
    return lab, cur

