lab0, n0 = components(decision==0)
sizes1 = {i: int((lab1==i).sum()) for i in range(1,n1+1)}
sizes0 = {i: int((lab0==i).sum()) for i in range(1,n0+1)}
print("n1:", n1, "sizes:", sorted(sizes1.values()))
print("n0:", n0, "sizes:", sorted(sizes0.values()))
iso1 = [list(map(int,np.argwhere(lab1==i)[0])) for i in sizes1 if sizes1[i]==1]
iso0 = [list(map(int,np.argwhere(lab0==i)[0])) for i in sizes0 if sizes0[i]==1]
