diff[1:,:] |= d[1:,:] != d[:-1,:]
diff[:-1,:] |= d[1:,:] != d[:-1,:]
diff[:,1:] |= d[:,1:] != d[:,:-1]
diff[:,:-1] |= d[:,1:] != d[:,:-1]
