    vals=[]
    for dr in (-1,0,1):
        for dc in (-1,0,1):
            rr,cc=r+dr,c+dc
            if 0<=rr<H and 0<=cc<W:
                vals.append(int(d[rr,cc]))
    vals=np.array(vals)
    u,p=np.unique(vals,return_counts=True)
    p=p/len(vals)
    return float(-(p*np.log2(p)).sum())
