# Boundary windows: adjacent (4-neighbor) to a window with a different decision
boundary = np.zeros_like(decision, dtype=bool)
for r in range(15):
    for c in range(15):
        neigh = []
        if r>0: neigh.append(decision[r-1,c])
        if r<14: neigh.append(decision[r+1,c])
        if c>0: neigh.append(decision[r,c-1])
        if c<14: neigh.append(decision[r,c+1])
        if neigh and any(n != decision[r,c] for n in neigh):
            boundary[r,c] = True
print("boundary count:", boundary.sum())

# Isolated: differs from ALL 4 neighbors
isolated = np.zeros_like(decision, dtype=bool)
for r in range(15):
    for c in range(15):
        neigh = []
        if r>0: neigh.append(decision[r-1,c])
        if r<14: neigh.append(decision[r+1,c])
        if c>0: neigh.append(decision[r,c-1])
        if c<14: neigh.append(decision[r,c+1])
        if neigh and all(n != decision[r,c] for n in neigh):
            isolated[r,c] = True
print("isolated count:", isolated.sum())
print("isolated windows:", [list(map(int,xy)) for xy in zip(*np.where(isolated))])

