for r in range(15):
    for c in range(15):
        nbrs = []
        for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            rr,cc = r+dr, c+dc
            if 0<=rr<15 and 0<=cc<15:
                nbrs.append(d[rr,cc])
        if nbrs and all(n != d[r,c] for n in nbrs):
            isolated[r,c] = True
print("isolated cells:", np.argwhere(isolated))
# boundary: cell has at least one neighbor with different decision
boundary = np.zeros_like(d, dtype=bool)
for r in range(15):
    for c in range(15):
        for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            rr,cc = r+dr, c+dc
            if 0<=rr<15 and 0<=cc<15 and d[rr,cc]!=d[r,c]:
                boundary[r,c]=True
print("boundary count:", boundary.sum())
# combined suspect: isolated OR low margin
low = margin < 0.5
print("low margin count:", low.sum())

